package com.grifplot.libros;
import java.io.*;import java.net.*;import java.util.*;
final class WebPdf {
 interface Progress {boolean cancelled();void update(long bytes,long total);}
 static void download(String url,String ua,String cookie,String referer,File file,Progress p)throws Exception {String current=url;HttpURLConnection c=null;String origin=new URL(url).getHost();for(int redirects=0;redirects<7;redirects++){if(p.cancelled())throw new IOException("Descarga cancelada");URL u=new URL(current);if(!"https".equalsIgnoreCase(u.getProtocol()))throw new IOException("Se requiere un enlace HTTPS para abrir el PDF");c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent",ua);c.setRequestProperty("Accept-Encoding","identity");if(origin.equalsIgnoreCase(u.getHost())&&cookie!=null)c.setRequestProperty("Cookie",cookie);if(referer!=null)c.setRequestProperty("Referer",referer);int code=c.getResponseCode();if(code>=300&&code<400){String dest=c.getHeaderField("Location");c.disconnect();if(dest==null)throw new IOException("Enlace redirigido no válido");current=new URL(u,dest).toString();c=null;continue;}if(code==401||code==403){c.disconnect();throw new IOException("El enlace requiere acceso o no permite descargar. Busca otro PDF público.");}if(code<200||code>=300){c.disconnect();throw new IOException("La fuente respondió con error "+code);}break;}if(c==null)throw new IOException("Demasiadas redirecciones");try(InputStream in=new BufferedInputStream(c.getInputStream());OutputStream out=new FileOutputStream(file)){long total=c.getContentLengthLong();if(total>1024L*1024*1024)throw new IOException("El PDF supera 1 GB");byte[] signature=new byte[5];int got=0,n;while(got<5&&(n=in.read(signature,got,5-got))>0)got+=n;if(got!=5||!new String(signature,"US-ASCII").equals("%PDF-"))throw new IOException("Este enlace abre una página web, no un PDF. En la fuente pulsa Descargar PDF o elige otro resultado.");out.write(signature);long done=5,last=0;byte[] buf=new byte[65536];while((n=in.read(buf))!=-1){if(p.cancelled())throw new IOException("Descarga cancelada");done+=n;if(done>1024L*1024*1024)throw new IOException("El PDF supera 1 GB");out.write(buf,0,n);if(System.currentTimeMillis()-last>250){p.update(done,total);last=System.currentTimeMillis();}}p.update(done,total);}finally{c.disconnect();}}
}
